bst.insert(3);
bst.insert(7);
bst.insert(1);
bst.insert(4);
bst.insert(6);
bst.insert(8);

TreeNode* ancestor = findAncestor(bst.root, 4); // 查找节点4的祖先节点
if (ancestor != nullptr) {
    cout << "Ancestor of 4: " << ancestor->val << endl;
}
else {
    cout << "Node 4 has no ancestor in the BST." << endl;
}
